/**
 * Presentation helpers for the audit trail.
 *
 * `ActivityEvent.summary` is written by the service layer and is authoritative;
 * these helpers only supply the verb chip and the day grouping the feed and the
 * per-issue panel both render, so the two views never disagree about what a
 * day boundary is.
 */
import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";

export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
  "organization.updated": "updated the organization",
  "project.created": "created a project",
  "project.updated": "updated a project",
  "project.archived": "archived a project",
  "project.restored": "restored a project",
  "issue.created": "created an issue",
  "issue.updated": "updated an issue",
  "issue.status_changed": "changed status",
  "issue.assigned": "assigned an issue",
  "issue.archived": "archived an issue",
  "issue.restored": "restored an issue",
  "comment.created": "commented",
  "comment.updated": "edited a comment",
  "comment.deleted": "deleted a comment",
  "member.invited": "invited a member",
  "member.joined": "joined the organization",
  "member.role_changed": "changed a role",
  "member.removed": "removed a member",
  "billing.plan_changed": "changed the plan",
  "flag.toggled": "toggled a feature flag",
};

export function activityLabel(action: ActivityAction): string {
  return ACTIVITY_LABELS[action] ?? action;
}

/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
export function activityDay(event: ActivityEvent): string {
  return event.occurredAt.slice(0, 10);
}

/**
 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
 * newest day first and newest event first within a day.
 */
export function groupEventsByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = activityDay(event);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([day, bucket]) => ({
      day,
      events: [...bucket].sort((a, b) =>
        b.occurredAt.localeCompare(a.occurredAt),
      ),
    }));
}
/**
 * Grouped audit trail; the export button needs `activity:export`.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { formatRelative } from "@/lib/date";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import type { ActivityGroup } from "@/types/activity";
import type { PlanId } from "@/types/billing";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { activityResource } from "../permission/resources";
import { activityLabel } from "./activity-labels";

export type ActivityFeedProps = {
  groups: readonly ActivityGroup[];
  actors: Readonly<Record<string, User>>;
  actor: Actor;
  /** The org's plan, so the CSV flag can be evaluated for this tenant. */
  plan?: PlanId;
};

export function ActivityFeed(props: ActivityFeedProps): ReactElement | null {
  const { groups, actors, actor, plan = "free" } = props;
  const resource = activityResource(actor.orgId);

  if (!can(actor, "activity:read", resource)) {
    return (
      <EmptyState
        title="Activity is not visible to your role"
        description="Ask an administrator if you need the audit trail."
      />
    );
  }

  // Two independent gates: the plan must include CSV export, and the actor
  // must hold `activity:export` (admin and above).
  const exportEnabled =
    isEnabled("csv_export", {
      orgId: actor.orgId,
      userId: actor.userId,
      plan,
      role: actor.role,
    }) && can(actor, "activity:export", resource);

  if (groups.length === 0) {
    return <EmptyState title="No activity recorded in this window" />;
  }

  return (
    <section className="activity-feed space-y-6">
      {exportEnabled ? (
        <div className="flex justify-end">
          <Button variant="secondary" size="sm">
            Export CSV
          </Button>
        </div>
      ) : null}

      {groups.map((group) => (
        <div key={group.day}>
          <h2 className="mb-2 text-sm font-medium text-neutral-500">
            {group.day}
          </h2>
          <ol className="space-y-2 border-l pl-4">
            {group.events.map((event) => {
              const author =
                event.actorId === null ? undefined : actors[event.actorId];
              return (
                <li key={event.id} className="flex items-start gap-2 text-sm">
                  {author !== undefined ? (
                    <Avatar
                      name={author.name}
                      src={author.avatarUrl}
                      size="xs"
                    />
                  ) : null}
                  <span>
                    <strong>{author?.name ?? "Taskflow"}</strong>{" "}
                    {activityLabel(event.action)} — {event.summary}
                    <span className="ml-2 text-neutral-500">
                      {formatRelative(event.occurredAt)}
                    </span>
                  </span>
                </li>
              );
            })}
          </ol>
        </div>
      ))}
    </section>
  );
}
