import { z } from "zod";
import { isValidTimeZone } from "@/lib/date";
import { orgIdSchema } from "./common";
import { slugSchema } from "./slug";
import { planIdSchema } from "./billing";

const issueStatusField = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);
const digestHourField = z.number().int().min(0).max(23);
/** An IANA zone name, e.g. "Asia/Tokyo"; anything `Intl` rejects is refused. */
const timeZoneField = z
  .string()
  .refine(isValidTimeZone, { error: "Unknown time zone" });

export const organizationSettingsSchema = z.object({
  defaultIssueStatus: issueStatusField.default("backlog"),
  allowPublicProjects: z.boolean().default(false),
  requireTwoFactor: z.boolean().default(false),
  digestHourUtc: digestHourField.default(7),
  timeZone: timeZoneField.default("UTC"),
  enabledFlagOverrides: z.array(z.string()).default([]),
});

/**
 * A settings patch: only the keys the caller sent. Unlike
 * `organizationSettingsSchema().partial()` no defaults are filled in, so
 * patching one setting can never reset another (say, the time zone) to its
 * default.
 */
export const organizationSettingsPatchSchema = z.object({
  defaultIssueStatus: issueStatusField.optional(),
  allowPublicProjects: z.boolean().optional(),
  requireTwoFactor: z.boolean().optional(),
  digestHourUtc: digestHourField.optional(),
  timeZone: timeZoneField.optional(),
  enabledFlagOverrides: z.array(z.string()).optional(),
});

export const createOrganizationSchema = z.object({
  name: z.string().min(2).max(64),
  slug: slugSchema,
  plan: planIdSchema.default("free"),
});

