import { toIsoTimestamp } from "@/types/common";
import { isOverdue, localDate, parseIso, startOfLocalDate } from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";
import type { ReactElement } from "react";

export type IssueDueDateFieldProps = {
  value: IsoTimestamp | null;
  onChange: (value: IsoTimestamp | null) => void;
  /** The workspace's zone: a due date is a whole day on its clock. */
  timeZone?: string;
};

/** The picker speaks `YYYY-MM-DD`; the domain stores full ISO timestamps. */
export function toDateInputValue(
  value: IsoTimestamp | null,
  timeZone = "UTC",
): string | null {
  return value === null ? null : localDate(value, timeZone);
}

export function fromDateInputValue(
  value: string | null,
  timeZone = "UTC",
): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  // The last instant of that day on the workspace clock.
  const next = new Date(`${value}T00:00:00.000Z`);
  next.setUTCDate(next.getUTCDate() + 1);
  const nextStart = startOfLocalDate(next.toISOString().slice(0, 10), timeZone);
  return toIsoTimestamp(new Date(parseIso(nextStart).getTime() - 1));
}

export function IssueDueDateField(
  props: IssueDueDateFieldProps,
): ReactElement | null {
  const { timeZone = "UTC" } = props;
  const overdue = isOverdue(props.value, new Date(), timeZone);

  return (
    <div className="space-y-1">
      <DatePicker
        value={toDateInputValue(props.value, timeZone)}
        placeholder="No due date"
        onChange={(value) => props.onChange(fromDateInputValue(value, timeZone))}
      />
      {overdue ? (
        <p className="text-xs text-red-600">This issue is past its due date.</p>
      ) : null}
    </div>
  );
}
'''
