/**
 * The retention sweep's cut-off is local midnight on the workspace's clock,
 * `retentionDays` calendar days back — not `retentionDays × 24h` before now.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { getPlanLimits } from "@/config/plan-limits";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;

const NOW = new Date("2026-03-15T12:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function makeTenant(slug: string, timeZone: string): Promise<Tenant> {
  const tenant = await createTenant(slug, "free");
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { timeZone },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function recordAt(tenant: Tenant, occurredAt: string): Promise<void> {
  await activityRepo.insertActivity({
    orgId: tenant.org.id,
    action: "issue.created",
    actorId: null,
    subjectKind: "issue",
    subjectId: "iss_1",
    projectId: null,
    summary: occurredAt,
    metadata: {},
    occurredAt: occurredAt as IsoTimestamp,
  });
}

async function survivors(tenant: Tenant): Promise<readonly string[]> {
  const page = await activityRepo.listActivity({
    orgId: tenant.org.id,
    limit: 100,
    cursor: null,
  });
  return page.items.map((event) => event.summary).sort();
}

describe("jobs/cleanup-archived-job", () => {
  it("relies on the free plan keeping 30 days", () => {
    expect(getPlanLimits("free").retentionDays).toBe(30);
  });

  it("cuts off at local midnight of the date retentionDays back", async () => {
    // 21:00 on 15 March in Tokyo; 30 days back is 13 February, whose local
    // midnight is 2026-02-12T15:00Z. (30 × 24h before now would be 12:00Z.)
    const tenant = await makeTenant("cleanup-tokyo", "Asia/Tokyo");
    await recordAt(tenant, "2026-02-12T14:59:59.999Z");
    await recordAt(tenant, "2026-02-12T15:00:00.000Z");
    await recordAt(tenant, "2026-02-13T06:00:00.000Z");

    const result = await runCleanupArchivedJob(NOW);

    expect(result.failed).toBe(0);
    expect(await survivors(tenant)).toEqual([
      "2026-02-12T15:00:00.000Z",
      "2026-02-13T06:00:00.000Z",
    ]);
  });

  it("counts calendar days, not 24-hour blocks, across a DST change", async () => {
    // New York sprang forward on 8 March: 13 February 00:00 EST is 05:00Z,
    // although exactly 720 hours before today's local midnight is 04:00Z.
