import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("orgzone", "growth");
});

afterAll(() => {
  cleanup();
});

describe("repositories/organization-repository time zone", () => {
  it("defaults a new workspace to UTC", async () => {
    expect(tenant.org.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");
  });

  it("stores the zone with the other settings and reads it back everywhere", async () => {
    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });
    expect(updated.settings.timeZone).toBe("Asia/Tokyo");

    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");
    expect((await orgRepo.findOrgBySlug("orgzone"))?.settings.timeZone).toBe("Asia/Tokyo");
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.settings.timeZone).toBe("Asia/Tokyo");
    expect(await orgRepo.findOrgTimeZone(tenant.org.id)).toBe("Asia/Tokyo");
  });

  it("keeps the zone when another setting is patched", async () => {
    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 5 },
    });
    expect(updated.settings).toMatchObject({ digestHourUtc: 5, timeZone: "Asia/Tokyo" });
  });

  it("refuses an unknown zone with a RangeError and changes nothing", async () => {
    const before = await orgRepo.findOrgById(tenant.org.id);

    await expect(
      orgRepo.updateOrg(tenant.org.id, {
        orgId: tenant.org.id,
        name: "Renamed",
        settings: { digestHourUtc: 9, timeZone: "Mars/Olympus" },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const after = await orgRepo.findOrgById(tenant.org.id);
    expect(after).toEqual(before);
  });

  it("refuses an unknown zone through the service too, without an audit entry", async () => {
    const before = await orgRepo.findOrgById(tenant.org.id);

    await expect(
      orgService.updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        settings: { timeZone: "Not/AZone" },
      }),
    ).rejects.toBeInstanceOf(RangeError);
    expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(before);

    const updated = await orgService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { timeZone: "America/New_York" },
    });
    expect(updated.settings.timeZone).toBe("America/New_York");
  });
});
