/** Organization settings: the workspace time zone and how a patch is parsed. */
import { describe, expect, it } from "vitest";
import {
  organizationSettingsSchema,
  updateOrganizationSchema,
} from "@/schemas/organization";
import { ORG_A } from "../helpers/factories";

describe("schemas/organization", () => {
  it("defaults the time zone to UTC", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
  });

  it("accepts a zone Intl recognises", () => {
    expect(organizationSettingsSchema.parse({ timeZone: "Asia/Tokyo" }).timeZone).toBe("Asia/Tokyo");
    expect(organizationSettingsSchema.parse({ timeZone: "America/New_York" }).timeZone).toBe(
      "America/New_York",
    );
  });

  it("rejects an unknown zone", () => {
    for (const timeZone of ["Mars/Olympus", "", "Tokyo", 5]) {
      expect(organizationSettingsSchema.safeParse({ timeZone }).success, String(timeZone)).toBe(false);
    }
    expect(
      updateOrganizationSchema.safeParse({ orgId: ORG_A, settings: { timeZone: "Mars/Olympus" } })
        .success,
    ).toBe(false);
  });

  it("does not fill in defaults for a settings patch", () => {
    // Patching one setting must not reset another (say, the zone) to its default.
    const parsed = updateOrganizationSchema.parse({
      orgId: ORG_A,
      settings: { digestHourUtc: 9 },
    });
    expect(parsed.settings).toEqual({ digestHourUtc: 9 });

    const zone = updateOrganizationSchema.parse({
      orgId: ORG_A,
      settings: { timeZone: "Asia/Tokyo" },
    });
    expect(zone.settings).toEqual({ timeZone: "Asia/Tokyo" });
  });
});
