import { it, expect } from "vitest";
import Database from "better-sqlite3";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";

it("adds time_zone to an older organizations table", async () => {
  const dir = mkdtempSync(join(tmpdir(), "mig-"));
  const path = join(dir, "old.db");
  const old = new Database(path);
  old.exec(`CREATE TABLE organizations (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, owner_id TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'free', logo_url TEXT, trial_ends_at TEXT, default_issue_status TEXT NOT NULL DEFAULT 'backlog', allow_public_projects INTEGER NOT NULL DEFAULT 0, require_two_factor INTEGER NOT NULL DEFAULT 0, digest_hour_utc INTEGER NOT NULL DEFAULT 7, enabled_flag_overrides TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT)`);
  old.exec(`INSERT INTO organizations (id,name,slug,owner_id,created_at,updated_at) VALUES ('o1','n','s','u','a','b')`);
  old.close();
  await runMigrations(path);
  await runMigrations(path);
  const db = new Database(path);
  expect(db.prepare("SELECT time_zone FROM organizations").get()).toEqual({ time_zone: "UTC" });
  db.close();
});
EOF
